fix:
Group the boundaries into a single cohesive type that enforces the range invariant inside its constructor.
```rust
struct DateRange {
    start: NaiveDate,
    end: NaiveDate,
}

impl DateRange {
    pub fn new(start: NaiveDate, end: NaiveDate) -> Result<Self, String> {
        if start <= end {
            Ok(DateRange { start, end })
        } else {
            Err("Start date must be before or equal to end date".into())
        }
    }
}
